import{_ as t,o as a,c as i,a0 as n}from"./chunks/framework.DzvPB4Y-.js";const m=JSON.parse('{"title":"Time and Resources · Gantt","description":"","frontmatter":{},"headers":[],"relativePath":"frameworks/gantt/index.md","filePath":"frameworks/gantt/index.md"}'),o={name:"frameworks/gantt/index.md"};function r(s,e,l,d,c,h){return a(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="time-and-resources-·-gantt" tabindex="-1">Time and Resources · Gantt <a class="header-anchor" href="#time-and-resources-·-gantt" aria-label="Permalink to &quot;Time and Resources · Gantt&quot;">​</a></h1><p>Choose execution modes and start times while jointly reserving machines, people and other resources, respecting dependencies, calendars and material events. The first lesson uses finite-candidate activity MILP, without first turning activities into paths.</p><h2 id="minimum-vocabulary" tabindex="-1">Minimum Vocabulary <a class="header-anchor" href="#minimum-vocabulary" aria-label="Permalink to &quot;Minimum Vocabulary&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Concept</th><th>API</th><th>Input or output</th></tr></thead><tbody><tr><td>Activity</td><td><code>Activity</code></td><td>Work unit; cancellation needs an explicit cost</td></tr><tr><td>Mode</td><td><code>ActivityMode</code></td><td>Duration, allowed starts, cost and reservation intervals</td></tr><tr><td>Resource</td><td><code>ActivityResource</code></td><td>Capacity, unavailable intervals and time-varying capacity</td></tr><tr><td>Dependency</td><td><code>ActivityDependency</code></td><td>Endpoint relations and time bounds</td></tr><tr><td>Problem and output</td><td><code>ActivitySchedulingProblem</code> / <code>ActivitySchedule</code></td><td>Candidates, schedule, reservations, cancellations and inventory</td></tr></tbody></table><p>Allowed starts define the business domain, not a search budget. Supplying 08:00 and 10:00 does not implicitly permit 09:00. Resource reservations are half-open intervals; availability at the start alone is insufficient.</p><h2 id="entry-points" tabindex="-1">Entry Points <a class="header-anchor" href="#entry-points" aria-label="Permalink to &quot;Entry Points&quot;">​</a></h2><p>Both languages offer <code>ActivitySchedulingApplicationService</code>. Standalone services and embedded contexts share domain registration. Reusing the MILP capability of <code>ColumnGenerationSolver</code> does not make this activity path a column-generation algorithm.</p><p>APS / MPS / LSP are business-level markers, not the standalone solving entry for this lesson. Task-bunch, capacity and branch-and-price paths come later.</p><h2 id="boundaries" tabindex="-1">Boundaries <a class="header-anchor" href="#boundaries" aria-label="Permalink to &quot;Boundaries&quot;">​</a></h2><ul><li>This is not a promise of arbitrary continuous-time scheduling, automatic preemption/batching or complete industry regulations.</li><li>Calendar downtime does not automatically mean pausing and resuming an activity.</li><li>Joint resources and material inventory have separate contracts; skill-pool capacity does not replace named-person exclusivity.</li><li>Ordinary Gantt does not require Network. Evaluate composition for travel subproblems across locations.</li></ul><h2 id="learning-path" tabindex="-1">Learning Path <a class="header-anchor" href="#learning-path" aria-label="Permalink to &quot;Learning Path&quot;">​</a></h2><ol><li>Complete <a href="./../setup.html">environment setup</a>.</li><li>Follow <a href="./first-schedule.html">your first activity schedule</a>, checking modes, precedence and reservations.</li><li>Add downtime, baseline changes and material events. Distinguish execution facts from decisions still being optimized.</li><li>Read <a href="/ospf/guide/rolling-optimization.html">rolling optimization</a>, then the <a href="/ospf/examples/framework-example4.html">flight-recovery example</a>.</li></ol><h2 id="reference" tabindex="-1">Reference <a class="header-anchor" href="#reference" aria-label="Permalink to &quot;Reference&quot;">​</a></h2><ul><li><a href="https://github.com/fuookami/ospf-kotlin/blob/main/ospf-kotlin-framework-gantt-scheduling/gantt-scheduling-domain-activity-context/README.md" target="_blank" rel="noreferrer">Kotlin activity contracts</a></li><li><a href="https://github.com/fuookami/ospf-rust/blob/main/ospf-rust-framework-gantt-scheduling/src/domain/activity/README.md" target="_blank" rel="noreferrer">Rust activity contracts</a></li></ul><p><a href="./../">Back to scenario selection</a></p><h2 id="continue-practicing" tabindex="-1">Continue Practicing <a class="header-anchor" href="#continue-practicing" aria-label="Permalink to &quot;Continue Practicing&quot;">​</a></h2><p>Next: <a href="./business-scenario.html">Calendars and Rolling Recovery</a>. Before adapting the scenario to your application, complete the <a href="./../integration.html">business integration checks</a>.</p>',17)])])}const p=t(o,[["render",r]]);export{m as __pageData,p as default};
